mapper.select:
SELECT *
FROM ai_knowledge_document
WHERE organization_id = #{orgId}

    AND (
        name LIKE CONCAT('%', #{request.keyword}, '%')
        OR original_name LIKE CONCAT('%', #{request.keyword}, '%')
        OR remark LIKE CONCAT('%', #{request.keyword}, '%')
    )


    AND file_type = #{request.fileType}


    AND category = #{request.category}


    AND parse_status = #{request.parseStatus}


    AND enabled = #{request.enabled}

ORDER BY update_time DESC

SELECT *
FROM ai_knowledge_chunk
WHERE organization_id = #{orgId}
  AND document_id = #{documentId}
ORDER BY chunk_index ASC

SELECT c.* FROM ai_knowledge_chunk c INNER JOIN ai_knowledge_document d ON d.id = c.document_id WHERE c.organization_id = #{orgId} AND d.organization_id = #{orgId} AND c.enabled = 1 AND d.enabled = 1 AND d.parse_status = 'PARSED' AND (d.category IS NULL OR d.category != 'SEMANTIC_RULE') AND ( c.content LIKE CONCAT('%', #{question}, '%')
OR c.content LIKE CONCAT('%', #{keyword}, '%') OR c.title LIKE CONCAT('%', #{keyword}, '%') OR d.name LIKE CONCAT('%', #{keyword}, '%')
) ORDER BY c.update_time DESC LIMIT #{limit}

SELECT *
FROM ai_knowledge_document
WHERE id = #{documentId}
  AND organization_id = #{orgId}
FOR UPDATE

mapper.update:
UPDATE ai_knowledge_parse_job
SET status = #{status},
    step = #{step},
    message = #{message},
    error_stack = #{errorStack},
    start_time = #{startTime},
    finish_time = #{finishTime},
    update_time = #{updateTime}
WHERE id = #{jobId}
  AND organization_id = #{orgId}

UPDATE ai_knowledge_document
SET parse_status = #{parseStatus},
    parse_error = #{parseError},

    chunk_count = #{chunkCount},

    update_user = #{updateUser},
    update_time = #{updateTime}
WHERE id = #{documentId}
  AND organization_id = #{orgId}

mapper.select:
SELECT id
FROM ai_knowledge_parse_job
WHERE status = 'RUNNING'
  AND COALESCE(start_time, update_time, create_time) <= #{staleBefore}
ORDER BY COALESCE(start_time, update_time, create_time) ASC, id ASC
LIMIT #{limit}

SELECT c.*
FROM ai_knowledge_chunk c
INNER JOIN ai_knowledge_document d ON d.id = c.document_id
WHERE c.organization_id = #{orgId}
  AND d.organization_id = #{orgId}
  AND d.id = #{request.documentId}
  AND d.category = 'SEMANTIC_RULE'

    AND (
        c.title LIKE CONCAT('%', #{request.keyword}, '%')
        OR c.content LIKE CONCAT('%', #{request.keyword}, '%')
    )


    AND JSON_UNQUOTE(JSON_EXTRACT(c.content, '$.review.status')) = #{request.reviewStatus}

ORDER BY c.chunk_index ASC

SELECT c.*
FROM ai_knowledge_chunk c
INNER JOIN ai_knowledge_document d ON d.id = c.document_id
WHERE c.id = #{chunkId}
  AND c.organization_id = #{orgId}
  AND d.organization_id = #{orgId}
  AND d.category = 'SEMANTIC_RULE'
LIMIT 1

SELECT *
FROM ai_knowledge_document
WHERE id = #{documentId}
  AND organization_id = #{orgId}
  AND category = 'SEMANTIC_RULE'
FOR UPDATE

