mapper.select:
SELECT c.*
FROM ai_knowledge_chunk c
INNER JOIN ai_knowledge_document d ON d.id = c.document_id
WHERE c.document_id = #{documentId}
  AND c.organization_id = #{orgId}
  AND d.organization_id = #{orgId}
  AND d.category = 'SEMANTIC_RULE'
ORDER BY c.chunk_index ASC

SELECT c.*
FROM ai_knowledge_chunk c
INNER JOIN ai_knowledge_document d ON d.id = c.document_id
WHERE c.organization_id = #{orgId}
  AND d.organization_id = #{orgId}
  AND d.category = 'SEMANTIC_RULE'
  AND JSON_UNQUOTE(JSON_EXTRACT(c.content, '$.ruleId')) = #{ruleId}
ORDER BY CAST(JSON_UNQUOTE(JSON_EXTRACT(c.content, '$.version')) AS UNSIGNED) DESC,
         c.update_time DESC

SELECT c.*
FROM ai_knowledge_chunk c
INNER JOIN ai_knowledge_document d ON d.id = c.document_id
WHERE c.organization_id = #{orgId}
  AND d.organization_id = #{orgId}
  AND d.category = 'SEMANTIC_RULE'
  AND JSON_UNQUOTE(JSON_EXTRACT(c.content, '$.ruleId')) = #{ruleId}
  AND CAST(JSON_UNQUOTE(JSON_EXTRACT(c.content, '$.version')) AS UNSIGNED) = #{version}
LIMIT 1

SELECT COALESCE(MAX(CAST(JSON_UNQUOTE(JSON_EXTRACT(c.content, '$.version')) AS UNSIGNED)), 0)
FROM ai_knowledge_chunk c
INNER JOIN ai_knowledge_document d ON d.id = c.document_id
WHERE c.organization_id = #{orgId}
  AND d.organization_id = #{orgId}
  AND d.category = 'SEMANTIC_RULE'
  AND JSON_UNQUOTE(JSON_EXTRACT(c.content, '$.ruleId')) = #{ruleId}

mapper.update:
UPDATE ai_knowledge_chunk c
INNER JOIN ai_knowledge_document d ON d.id = c.document_id
SET c.enabled = 0,
    c.update_user = #{updateUser},
    c.update_time = #{updateTime}
WHERE c.organization_id = #{orgId}
  AND d.organization_id = #{orgId}
  AND d.category = 'SEMANTIC_RULE'
  AND c.id != #{exceptChunkId}
  AND JSON_UNQUOTE(JSON_EXTRACT(c.content, '$.ruleId')) = #{ruleId}

